# Recursive function to calculate factorial
def factorial(n):
    """Calculate the factorial of a number recursively."""
    # Base case
    if n == 0 or n == 1:
        return 1
    # Recursive case
    else:
        return n * factorial(n - 1)

# Test the function
print(factorial(5))  # Output: 120 (5 * 4 * 3 * 2 * 1)
